CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issuer text NOT NULL, subject text NOT NULL,
 name text NOT NULL, email text, suspended boolean NOT NULL DEFAULT false, auth_version integer NOT NULL DEFAULT 1,
 timezone text NOT NULL DEFAULT 'America/Chicago', identity_checked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(issuer,subject)
);
CREATE TABLE roles (user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('member','support','approver','service-admin','network-admin','identity-admin','owner')), scope text NOT NULL DEFAULT '*', source text NOT NULL DEFAULT 'operator', PRIMARY KEY(user_id,role,scope,source));
CREATE TABLE identity_links (user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL CHECK(provider IN ('pocket-id','netbird')), external_id text NOT NULL, verified_by uuid REFERENCES users(id), verified_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,provider), UNIQUE(provider,external_id));
CREATE TABLE sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, auth_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), authenticated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE oidc_flows (id text PRIMARY KEY, data text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, summary text NOT NULL, visibility text NOT NULL CHECK(visibility IN ('discoverable','entitled','admin')), metadata jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE favorites (user_id uuid REFERENCES users(id), service_id uuid REFERENCES services(id) ON DELETE CASCADE, PRIMARY KEY(user_id,service_id));
CREATE TABLE service_dependencies (service_id uuid REFERENCES services(id) ON DELETE CASCADE, dependency_id uuid REFERENCES services(id), required boolean NOT NULL DEFAULT true, PRIMARY KEY(service_id,dependency_id), CHECK(service_id<>dependency_id));
CREATE TABLE entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, name text NOT NULL, policy jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1);
CREATE TABLE service_entitlements (service_id uuid REFERENCES services(id) ON DELETE CASCADE, entitlement_id uuid REFERENCES entitlements(id), PRIMARY KEY(service_id,entitlement_id));
CREATE TABLE prerequisites (entitlement_id uuid REFERENCES entitlements(id), prerequisite_id uuid REFERENCES entitlements(id), PRIMARY KEY(entitlement_id,prerequisite_id), CHECK(entitlement_id<>prerequisite_id));
CREATE TABLE bundles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, requestable boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE bundle_items (bundle_id uuid REFERENCES bundles(id), entitlement_id uuid REFERENCES entitlements(id), PRIMARY KEY(bundle_id,entitlement_id));
CREATE TABLE bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entitlement_id uuid NOT NULL REFERENCES entitlements(id), provider text NOT NULL CHECK(provider IN ('pocket-id','netbird','manual','wow-manager','mock')), external_id text, configuration jsonb NOT NULL DEFAULT '{}', managed boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, UNIQUE(entitlement_id,provider,external_id));
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES users(id), assignee_id uuid REFERENCES users(id), service_id uuid REFERENCES services(id), type text NOT NULL, subject text NOT NULL, description text NOT NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tickets_requester ON tickets(requester_id,updated_at);
CREATE TABLE ticket_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, private boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), ticket_id uuid NOT NULL UNIQUE REFERENCES tickets(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','needs-information','approved','denied','canceled')), snapshot jsonb NOT NULL, duration_hours integer NOT NULL CHECK(duration_hours>0), reason text NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES access_requests(id), actor_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL, reason text NOT NULL, duration_hours integer, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_id,actor_id));
CREATE TABLE grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), entitlement_id uuid NOT NULL REFERENCES entitlements(id), request_id uuid REFERENCES access_requests(id), source text NOT NULL, desired boolean NOT NULL DEFAULT true, expires_at timestamptz, fulfillment text NOT NULL DEFAULT 'queued', version integer NOT NULL DEFAULT 1, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX grants_effective ON grants(user_id,entitlement_id) WHERE desired;
CREATE TABLE fulfillment_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grant_id uuid NOT NULL REFERENCES grants(id), binding_id uuid NOT NULL REFERENCES bindings(id), status text NOT NULL DEFAULT 'queued', error text, observed jsonb, attested_by uuid REFERENCES users(id), attested_at timestamptz, UNIQUE(grant_id,binding_id));
CREATE TABLE managed_edges (provider text NOT NULL, resource_id text NOT NULL, subject_id text NOT NULL, added boolean NOT NULL DEFAULT false, observed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,resource_id,subject_id));
CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), external_id text NOT NULL UNIQUE, metadata jsonb NOT NULL, observed_at timestamptz NOT NULL DEFAULT now(), lost_at timestamptz);
CREATE TABLE network_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid REFERENCES services(id), external_id text NOT NULL UNIQUE, metadata jsonb NOT NULL, managed boolean NOT NULL DEFAULT false);
CREATE TABLE setup_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), external_id text NOT NULL UNIQUE, metadata jsonb NOT NULL, revoked_at timestamptz);
CREATE TABLE guides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, visibility text NOT NULL DEFAULT 'members', service_id uuid REFERENCES services(id), required boolean NOT NULL DEFAULT false, current_version integer NOT NULL DEFAULT 1);
CREATE TABLE guide_versions (guide_id uuid REFERENCES guides(id), version integer NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(guide_id,version));
CREATE TABLE acknowledgments (user_id uuid REFERENCES users(id), guide_id uuid NOT NULL, version integer NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,guide_id,version), FOREIGN KEY(guide_id,version) REFERENCES guide_versions(guide_id,version));
CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid REFERENCES tickets(id), guide_id uuid REFERENCES guides(id), uploader_id uuid NOT NULL REFERENCES users(id), storage_key text NOT NULL UNIQUE, name text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size>0 AND size<=5242880), created_at timestamptz NOT NULL DEFAULT now(), CHECK((ticket_id IS NOT NULL)::integer+(guide_id IS NOT NULL)::integer=1));
CREATE TABLE onboarding (user_id uuid REFERENCES users(id), step text NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,step));
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, created_by uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, revoked_at timestamptz, consumed_by uuid REFERENCES users(id), consumed_at timestamptz);
CREATE TABLE health_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid NOT NULL REFERENCES services(id), kind text NOT NULL CHECK(kind IN ('http','tcp','manual','kuma','incoming')), config jsonb NOT NULL, interval_seconds integer NOT NULL DEFAULT 60 CHECK(interval_seconds>=30), enabled boolean NOT NULL DEFAULT true, next_run timestamptz NOT NULL DEFAULT now());
CREATE TABLE health_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), check_id uuid NOT NULL REFERENCES health_checks(id), state text NOT NULL CHECK(state IN ('healthy','degraded','down','unknown')), source text NOT NULL, vantage text NOT NULL, details jsonb NOT NULL DEFAULT '{}', observed_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX observations_recent ON health_observations(check_id,observed_at DESC);
CREATE TABLE maintenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid REFERENCES services(id), title text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), CHECK(ends_at>starts_at));
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid REFERENCES services(id), title text NOT NULL, state text NOT NULL CHECK(state IN ('investigating','identified','monitoring','resolved')), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid REFERENCES incidents(id), actor_id uuid REFERENCES users(id), body text NOT NULL, state text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid REFERENCES services(id), title text NOT NULL, body text NOT NULL, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, body text NOT NULL, link text NOT NULL, dedupe text NOT NULL UNIQUE, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_preferences (user_id uuid REFERENCES users(id), channel text NOT NULL, enabled boolean NOT NULL DEFAULT false, PRIMARY KEY(user_id,channel));
CREATE TABLE delivery_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_id uuid REFERENCES notifications(id), channel text NOT NULL, status text NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), subject_id uuid REFERENCES users(id), target text NOT NULL, action text NOT NULL, outcome text NOT NULL, correlation_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_recent ON audit_events(created_at DESC);
CREATE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit is append only'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, user_id uuid REFERENCES users(id), payload jsonb NOT NULL, dedupe text NOT NULL UNIQUE, priority integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token text, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON jobs(priority DESC,available_at) WHERE status IN ('queued','running');
CREATE TABLE worker_heartbeats (id text PRIMARY KEY, seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, status text NOT NULL, details jsonb NOT NULL DEFAULT '{}', started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE secret_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, ciphertext text NOT NULL, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_nonces (nonce text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
